// Zweck: Antwort von OpenRouter in das bisherige Paketformat bringen und Tokens und Kosten aus usage merken.
const r = $input.first().json;
const wahl = (r.choices || [])[0] || {};
const inhalt = String((wahl.message || {}).content || '');
// Warum Codeblock entfernen: manche Modelle setzen das JSON trotz Vorgabe zwischen drei Backticks.
const roh = inhalt.replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '');
let paket;
try { paket = JSON.parse(roh); } catch (e) { throw new Error('Antwort ist kein gültiges JSON (finish_reason ' + (wahl.finish_reason || 'unbekannt') + ')'); }
// Warum hier pruefen: fehlt ein Pflichtfeld, springt wie beim Structured Output Parser das Ersatzmodell ein (F3).
const pflicht = ['folien', 'caption_instagram', 'hashtags', 'linkedin_post', 'bildprompt'];
const fehlt = pflicht.filter(f => paket[f] === undefined);
if (fehlt.length) throw new Error('Paket ohne Pflichtfelder: ' + fehlt.join(', '));
// Warum usage: OpenRouter liefert Tokens und Kosten in USD schon fertig mit (usage.cost), keine Preistabelle noetig.
const u = r.usage || {};
const zahl = v => (typeof v === 'number' && isFinite(v)) ? v : null;
return [{ json: {
  output: paket,
  modell_antwort: r.model || '',
  token_prompt: zahl(u.prompt_tokens),
  token_antwort: zahl(u.completion_tokens),
  token_gesamt: zahl(u.total_tokens),
  kosten_usd: zahl(u.cost)
} }];
